RTL_SPLAY_LINKS * WINAPI RtlSubtreeSuccessor(RTL_SPLAY_LINKS *links)
{
    RTL_SPLAY_LINKS *child;

    TRACE("(%p)\n", links);

    child = RtlRightChild(links);
    if (!child)
        return NULL;

    while (RtlLeftChild(child))
        child = RtlLeftChild(child);

    return child;
}
